<template>
  <Popover v-model:open="isOpen">
    <div :class="['relative', buttonClass]">
      <PopoverTrigger as-child>
        <Button
          variant="outline"
          :class="cn('justify-start text-left font-normal pr-8 h-10', buttonClass, !value && 'text-muted-foreground')"
        >
          <CalendarIcon
            v-if="isIcon"
            :class="cn('mr-2 h-4 w-4', !value.end && !value.start && 'text-muted-foreground')"
          />
          <template v-if="value?.start && value.end">
            {{
              formatter.custom(toDate(value.start), {
                dateStyle: 'short',
              })
            }}
            -
            {{
              formatter.custom(toDate(value.end), {
                dateStyle: 'short',
              })
            }}
          </template>
          <template v-else>
            <span class="text-muted-foreground">{{ emptyPlaceholder }}</span>
          </template>
        </Button>
      </PopoverTrigger>
      <span
        v-if="(value.start || value.end) && clearButton"
        class="absolute end-0 inset-y-0 flex items-center justify-center px-2 cursor-pointer"
      >
        <X class="w-5 h-5" @click.stop.prevent="clearDate" />
      </span>
    </div>
    <PopoverContent class="w-auto p-0" align="start">
      <RangeCalendar v-model="value" />
    </PopoverContent>
  </Popover>
</template>

<script setup lang="ts">
import { Calendar as CalendarIcon, X } from 'lucide-vue-next';
import { type DateRange, useDateFormatter } from 'reka-ui';

import { toDate } from 'reka-ui/date';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';

interface Props {
  buttonClass?: string;
  emptyPlaceholder?: string;
  isIcon?: boolean;
  clearButton?: boolean;
}

withDefaults(defineProps<Props>(), {
  buttonClass: '',
  emptyPlaceholder: 'mm/dd/yyyy — mm/dd/yyyy',
  isIcon: true,
  clearButton: false,
});

const value = defineModel<DateRange>('value', {
  default: {
    start: undefined,
    end: undefined,
  },
});

const locale = ref('en-US');
const formatter = useDateFormatter(locale.value);
const isOpen = defineModel<boolean>('open', { default: false });

function clearDate() {
  value.value = {
    start: undefined,
    end: undefined,
  };
  if (isOpen.value) isOpen.value = false;
}
</script>
